style.css:
@-moz-document domain("roblox.com") {
/* Replace Roblox logo with Queen logo */
    .navbar-logo {
        background-image: url("https://upload.wikimedia.org/wikipedia/commons/7/7c/Queen_logo.svg");
        background-size: contain;
        background-repeat: no-repeat;
        background-position: center;
        width: 200px; /* Adjust for Queen logo size */
        height: 50px;
    }
    .navbar-logo img {
        opacity: 0; /* Hide original Roblox logo */
    }

    /* Add Queen band banner to header */
    .navbar {
        background-image: url("https://i.pinimg.com/1200x/c7/c1/e5/c7c1e5525618990c94f920f0d8e8eabb.jpg");
        background-size: auto 100%;
        background-repeat: no-repeat;
        background-position: center;
    }
}
